/// 取流结果。
class MediaResult {
  final String url;
  final String referer;
  final List<String> playlist;

  /// HLS AES-128 密钥地址。
  final String keyUri;

  /// HLS AES-128 的 IV。
  final String keyIv;

  /// 播放时必须随请求发送的 Cookie（CDN 签名源需要）。
  final String cookies;

  /// 播放请求必须携带的 `Origin`（部分 CDN 会校验来源）。
  final String origin;

  const MediaResult({
    required this.url,
    required this.referer,
    required this.playlist,
    required this.keyUri,
    required this.keyIv,
    required this.cookies,
    required this.origin,
  });

  @override
  int get hashCode =>
      url.hashCode ^
      referer.hashCode ^
      playlist.hashCode ^
      keyUri.hashCode ^
      keyIv.hashCode ^
      cookies.hashCode ^
      origin.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is MediaResult &&
          runtimeType == other.runtimeType &&
          url == other.url &&
          referer == other.referer &&
          playlist == other.playlist &&
          keyUri == other.keyUri &&
          keyIv == other.keyIv &&
          cookies == other.cookies &&
          origin == other.origin;
}

